from collections import defaultdict
import sys, threading
input = lambda : sys.stdin.readline().rstrip()
sys.setrecursionlimit(10 ** 6)
threading.stack_size(2 ** 27)

def main():
	N = int(input())
	A = [int(x) for x in input().split()]
	G = [[] for _ in range(N)]
	for _ in range(N - 1):
		(x, y) = [int(x) - 1 for x in input().split()]
		G[x].append(y)
		G[y].append(x)
	B = [0] * N
	vals = defaultdict(set)
	res = [0]

	def fill_dfs(v, p):
		B[v] = A[v]
		if p != -1:
			B[v] ^= B[p]
		for u in G[v]:
			if u != p:
				fill_dfs(u, v)

	def calc_dfs(v, p):
		zero = False
		vals[v].add(B[v])
		for u in G[v]:
			if u != p:
				calc_dfs(u, v)
				if len(vals[v]) < len(vals[u]):
					(vals[v], vals[u]) = (vals[u], vals[v])
				for x in vals[u]:
					zero |= x ^ A[v] in vals[v]
				for x in vals[u]:
					vals[v].add(x)
				vals[u].clear()
		if zero:
			res[0] += 1
			vals[v].clear()
	fill_dfs(0, -1)
	calc_dfs(0, -1)
	print(res[0])
threading.Thread(target=main).start()
